files.genefer_stream27_merged_final_gs_pair_v1:
// Source-only canonical final GS pair, accepted k -> both outputs k+5.
// Existing BF supplies normalized lower output. Parallel upper normalization
// is k+3 then two registers; do not leave y0 unscaled or count this pipe free.
// Upper/lower sum inputs must be canonical<P, NOT the proposed lazy [0,2P).
module genefer_stream27_merged_final_gs_pair_v1 #(
    parameter logic [31:0] P=32'd104857601,
    parameter logic [31:0] Q=32'd4190109697,
    parameter logic [31:0] UPPER_SCALE=32'd1
) (
    input logic clk,rst_n,in_valid,
    input logic [31:0] u,v,normalized_lower_root,
    output logic out_valid,out_error,
    output logic [31:0] y0,y1
);
    wire [31:0] sum=u+v;
    wire [31:0] sum_reduced=sum>=P ? sum-P : sum;
    wire lower_valid,upper_valid;
    wire [31:0] unused_upper,lower,upper_normalized;
    logic [31:0] upper_delay[0:1];
    logic [1:0] upper_valid_delay;
    genefer_ntt_difdit_butterfly27 #(.P(P),.Q(Q)) lower_pipeline (
        .clk,.rst_n,.in_valid,.dif(1'b1),.u,.v,.w(normalized_lower_root),
        .out_valid(lower_valid),.y0(unused_upper),.y1(lower));
    genefer_stream27_montgomery_factored_v1 #(.P(P),.Q(Q)) upper_pipeline (
        .clk,.rst_n,.in_valid,.lhs(sum_reduced),.rhs(UPPER_SCALE),
        .out_valid(upper_valid),.result(upper_normalized));
    assign out_valid=lower_valid && upper_valid_delay[1] && !out_error;
    assign y0=upper_delay[1];assign y1=lower;
    always_ff @(posedge clk or negedge rst_n)begin
        if(!rst_n)begin
            upper_valid_delay<=0;out_error<=0;
        end else begin
            upper_valid_delay<={upper_valid_delay[0],upper_valid};
            if(upper_valid)upper_delay[0]<=upper_normalized;
            if(upper_valid_delay[0])upper_delay[1]<=upper_delay[0];
            if(lower_valid!=upper_valid_delay[1])out_error<=1;
        end
    end
    // synthesis translate_off
    initial if(UPPER_SCALE>=P)$fatal(1,"S_M2_NORMALIZATION_SCALE_RANGE");
    always @(posedge clk)if(rst_n && in_valid && (u>=P || v>=P || normalized_lower_root>=P))
        $fatal(1,"S_M2_FINAL_GS_CANONICAL_INPUT_REQUIRED");
    // synthesis translate_on
endmodule

files.genefer_stream27_mdc_fifo_smallreg_v1.sv:
// S-M1 only: same advance/reset/head calendar as frozen mdc_fifo_sync.
// DEPTH<=32 is an explicit logic shift chain, not a feed-through RAM.
// No data reset: filled masks stale data until DEPTH new advances after reset.
// Larger delays delegate unchanged to the frozen synchronous RAM helper.
module genefer_stream27_mdc_fifo_smallreg_v1 #(
    parameter int unsigned WORD_W=38,
    parameter int unsigned DEPTH=4
) (
    input logic clk,rst_n,advance,
    input logic [WORD_W-1:0] write_word,
    output logic [WORD_W-1:0] head
);
    generate if(DEPTH<=32)begin: short_logic
        localparam int FILL_W=$clog2(DEPTH+1);
        logic [FILL_W-1:0] filled;
        (* ramstyle = "logic" *) logic [WORD_W-1:0] chain[0:DEPTH-1];
        assign head=filled==FILL_W'(DEPTH) ? chain[DEPTH-1] : '0;
        always_ff @(posedge clk)if(advance)begin
            chain[0]<=write_word;
            for(int i=1;i<DEPTH;i=i+1)chain[i]<=chain[i-1];
        end
        always_ff @(posedge clk or negedge rst_n)begin
            if(!rst_n)filled<='0;
            else if(advance && filled!=FILL_W'(DEPTH))filled<=filled+FILL_W'(1);
        end
    end else begin: unchanged_deep_ram
        genefer_stream27_mdc_fifo_sync #(.WORD_W(WORD_W),.DEPTH(DEPTH)) original (
            .clk,.rst_n,.advance,.write_word,.head
        );
    end endgenerate
    // synthesis translate_off
    initial if(WORD_W<1 || DEPTH<1 || (DEPTH&(DEPTH-1))!=0)$fatal(1,"SM1_FIFO_PARAMETERS");
    // synthesis translate_on
endmodule

files.genefer_stream27_mdc_commutator_sm1_regi:
// P16-c additive composition of S-M1 FIFO binding and r17 registered-fault transport.
// Additive r17 registered-fault cell; physical slot timing unchanged on legal frames.
// Additive physical-slot successor. Compile with frozen commutator_sync.sv
// plus S-M1 smallreg_v1 for the bound FIFO; its deeper RAM delegate is unchanged.
// Every occupied output updates data/tags, including canceled generations.
// Finite tags MUST NOT be reused/re-enabled until old slots and commits drain.
module genefer_stream27_mdc_commutator_sm1_registered_v1 #(
    parameter int unsigned DATA_W = 27,
    parameter int unsigned PAYLOAD_W = 16,
    parameter int unsigned GEN_W = 8,
    parameter int unsigned DEPTH = 4,
    parameter int unsigned FRAME_T = 8,
    parameter int unsigned CONTEXTS = 1
) (
    input logic clk, rst_n,
    input logic in_slot_valid, frame_start,
    input logic [DATA_W-1:0] upper_in, lower_in,
    input logic [PAYLOAD_W-1:0] upper_payload, lower_payload,
    input logic context_in,
    input logic [GEN_W-1:0] generation_in,
    input logic [CONTEXTS-1:0] context_enabled,
    input logic [CONTEXTS*GEN_W-1:0] live_generations,
    // Registered OR of all stage errors freezes the chain after first fault.
    input logic quarantine,
    output logic out_slot_valid, out_frame_start, out_eligible, out_error,
    // Pre-edge diagnostic only. Never gate current work with this signal.
    output logic fault_pending,
    output logic [DATA_W-1:0] upper_out, lower_out,
    output logic [PAYLOAD_W-1:0] upper_payload_out, lower_payload_out,
    output logic context_out,
    output logic [GEN_W-1:0] generation_out
);
    localparam int unsigned COUNT_W = $clog2(FRAME_T+1);
    localparam int unsigned SHIFT = $clog2(DEPTH);
    typedef struct packed {
        logic valid;
        logic [DATA_W-1:0] data;
        logic [PAYLOAD_W-1:0] payload;
        logic owner;
        logic [GEN_W-1:0] generation;
    } word_t;
    localparam int unsigned WORD_W = $bits(word_t);
    logic [COUNT_W-1:0] remaining, offset, output_offset;
    logic frame_owner, output_owner;
    logic [GEN_W-1:0] frame_generation, output_generation;
    logic malformed, phase, advance, owner_bad, eligible;
    word_t x, y, head_upper, head_lower, write_upper, result_lower;
    logic [GEN_W-1:0] expected_generation;

    always_comb begin
        malformed = (frame_start && ((remaining != '0) || !in_slot_valid)) ||
                    (in_slot_valid && !frame_start && (remaining == '0)) ||
                    (!in_slot_valid && (remaining != '0)) ||
                    (in_slot_valid && (CONTEXTS == 1) && context_in) ||
                    (in_slot_valid && !frame_start && (remaining != '0) &&
                     ((context_in != frame_owner) || (generation_in != frame_generation)));
        phase = in_slot_valid && !frame_start && offset[SHIFT];
        x = '0; y = '0;
        x.valid = in_slot_valid; x.data = upper_in; x.payload = upper_payload;
        x.owner = context_in; x.generation = generation_in;
        y.valid = in_slot_valid; y.data = lower_in; y.payload = lower_payload;
        y.owner = context_in; y.generation = generation_in;
        write_upper = phase ? head_lower : x;
        result_lower = phase ? x : head_lower;
        owner_bad = (head_upper.valid != result_lower.valid) ||
                    (head_upper.valid && ((head_upper.owner != result_lower.owner) ||
                     (head_upper.generation != result_lower.generation))) ||
                    (head_upper.valid && (output_offset != '0) &&
                     ((head_upper.owner != output_owner) ||
                      (head_upper.generation != output_generation)));
        expected_generation = live_generations[GEN_W-1:0];
        if (CONTEXTS == 2)
            expected_generation = head_upper.owner ?
                GEN_W'(live_generations >> GEN_W) : live_generations[GEN_W-1:0];
        eligible = head_upper.valid && !owner_bad &&
                   (head_upper.generation == expected_generation) &&
                   (head_upper.owner ? ((CONTEXTS == 2) && context_enabled[CONTEXTS-1]) : context_enabled[0]);
        fault_pending = out_error || (!quarantine && (malformed || owner_bad));
        // One occupied/raw edge may advance on a newly detected fault.
        // Sticky out_error and external quarantine are registered authorities.
        advance = rst_n && !quarantine && !out_error;
    end

    genefer_stream27_mdc_fifo_smallreg_v1 #(.WORD_W(WORD_W), .DEPTH(DEPTH)) upper_fifo (
        .clk(clk), .rst_n(rst_n), .advance(advance), .write_word(write_upper), .head(head_upper));
    genefer_stream27_mdc_fifo_smallreg_v1 #(.WORD_W(WORD_W), .DEPTH(DEPTH)) lower_fifo (
        .clk(clk), .rst_n(rst_n), .advance(advance), .write_word(y), .head(head_lower));

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_slot_valid <= 1'b0; out_frame_start <= 1'b0;
            out_eligible <= 1'b0; out_error <= 1'b0;
            remaining <= '0; offset <= '0; output_offset <= '0;
        end else begin
            out_slot_valid <= 1'b0; out_frame_start <= 1'b0; out_eligible <= 1'b0;
            if (!quarantine && (malformed || owner_bad)) out_error <= 1'b1;
            if (advance) begin
                if (in_slot_valid) begin
                    if (frame_start) begin
                        remaining <= COUNT_W'(FRAME_T-1); offset <= COUNT_W'(1);
                        frame_owner <= context_in; frame_generation <= generation_in;
                    end else begin
                        remaining <= remaining - COUNT_W'(1); offset <= offset + COUNT_W'(1);
                    end
                end
                if (head_upper.valid) begin
                    out_slot_valid <= 1'b1;
                    out_frame_start <= (output_offset == '0);
                    out_eligible <= eligible;
                    output_offset <= (output_offset == COUNT_W'(FRAME_T-1)) ? '0 : output_offset + COUNT_W'(1);
                    if (output_offset == '0) begin
                        output_owner <= head_upper.owner; output_generation <= head_upper.generation;
                    end
                    upper_out <= head_upper.data; lower_out <= result_lower.data;
                    upper_payload_out <= head_upper.payload; lower_payload_out <= result_lower.payload;
                    context_out <= head_upper.owner; generation_out <= head_upper.generation;
                end
            end
        end
    end

    // synthesis translate_off
    initial begin
        if (DEPTH < 1 || (DEPTH & (DEPTH-1)) != 0 || FRAME_T < 2*DEPTH ||
            FRAME_T % (2*DEPTH) != 0 || DATA_W < 1 || PAYLOAD_W < 1 || GEN_W < 1 ||
            (CONTEXTS != 1 && CONTEXTS != 2)) $fatal(1, "SLOTS_PARAMETERS");
    end
    // synthesis translate_on
endmodule

files.genefer_stream27_mdc_commutator_sync.sv:
// Isolated S3 primitive. Synchronous lookahead RAM reads, no async RAM read.
// Dense frames of FRAME_T rows; gaps may have any nonnegative length.
// Each FIFO delays L clocks. Registered pair output is consumed next edge.
// Per-context cancellation changes live_generations/context_enabled externally;
// it NEVER clears/stalls FIFO state. Do not reuse a generation before drain.
module genefer_stream27_mdc_commutator_sync #(
    parameter int unsigned DATA_W = 27,
    parameter int unsigned PAYLOAD_W = 16,
    parameter int unsigned GEN_W = 8,
    parameter int unsigned DEPTH = 4,
    parameter int unsigned FRAME_T = 8,
    parameter int unsigned CONTEXTS = 2
) (
    input logic clk, rst_n,
    input logic in_valid, frame_start,
    input logic [DATA_W-1:0] upper_in, lower_in,
    input logic [PAYLOAD_W-1:0] upper_payload, lower_payload,
    input logic context_in,
    input logic [GEN_W-1:0] generation_in,
    input logic [CONTEXTS-1:0] context_enabled,
    input logic [CONTEXTS*GEN_W-1:0] live_generations,
    output logic out_valid, out_error,
    output logic [DATA_W-1:0] upper_out, lower_out,
    output logic [PAYLOAD_W-1:0] upper_payload_out, lower_payload_out,
    output logic context_out,
    output logic [GEN_W-1:0] generation_out
);
    localparam int unsigned COUNT_W = $clog2(FRAME_T+1);
    localparam int unsigned SHIFT = $clog2(DEPTH);
    typedef struct packed {
        logic valid;
        logic [DATA_W-1:0] data;
        logic [PAYLOAD_W-1:0] payload;
        logic owner;
        logic [GEN_W-1:0] generation;
    } word_t;
    localparam int unsigned WORD_W = $bits(word_t);
    logic [COUNT_W-1:0] remaining, offset;
    logic frame_owner;
    logic [GEN_W-1:0] frame_generation;
    logic malformed, phase, advance, owner_bad, eligible;
    word_t x, y, head_upper, head_lower, write_upper, result_lower;
    logic [GEN_W-1:0] expected_generation;

    always_comb begin
        malformed = (frame_start && ((remaining != '0) || !in_valid)) ||
                    (in_valid && !frame_start && (remaining == '0)) ||
                    (!in_valid && (remaining != '0)) ||
                    (in_valid && (CONTEXTS == 1) && context_in) ||
                    (in_valid && !frame_start && (remaining != '0) &&
                     ((context_in != frame_owner) || (generation_in != frame_generation)));
        phase = in_valid && !frame_start && offset[SHIFT];
        x = '0; y = '0;
        x.valid = in_valid; x.data = upper_in; x.payload = upper_payload;
        x.owner = context_in; x.generation = generation_in;
        y.valid = in_valid; y.data = lower_in; y.payload = lower_payload;
        y.owner = context_in; y.generation = generation_in;
        write_upper = phase ? head_lower : x;
        result_lower = phase ? x : head_lower;
        owner_bad = (head_upper.valid != result_lower.valid) ||
                    (head_upper.valid && ((head_upper.owner != result_lower.owner) ||
                     (head_upper.generation != result_lower.generation)));
        // Fixed mux for 1|2 contexts: no out-of-range dynamic select.
        expected_generation = live_generations[GEN_W-1:0];
        if (CONTEXTS == 2)
            expected_generation = head_upper.owner ?
                GEN_W'(live_generations >> GEN_W) : live_generations[GEN_W-1:0];
        eligible = head_upper.valid && !owner_bad &&
                   (head_upper.generation == expected_generation) &&
                   (head_upper.owner ? ((CONTEXTS == 2) && context_enabled[CONTEXTS-1]) : context_enabled[0]);
        advance = rst_n && !out_error && !malformed && !owner_bad;
    end

    genefer_stream27_mdc_fifo_sync #(.WORD_W(WORD_W), .DEPTH(DEPTH)) upper_fifo (
        .clk(clk), .rst_n(rst_n), .advance(advance), .write_word(write_upper), .head(head_upper));
    genefer_stream27_mdc_fifo_sync #(.WORD_W(WORD_W), .DEPTH(DEPTH)) lower_fifo (
        .clk(clk), .rst_n(rst_n), .advance(advance), .write_word(y), .head(head_lower));

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid <= 1'b0; out_error <= 1'b0;
            remaining <= '0; offset <= '0;
        end else begin
            out_valid <= 1'b0;
            if (malformed || owner_bad) out_error <= 1'b1;
            if (advance) begin
                if (in_valid) begin
                    if (frame_start) begin
                        remaining <= COUNT_W'(FRAME_T-1); offset <= COUNT_W'(1);
                        frame_owner <= context_in; frame_generation <= generation_in;
                    end else begin
                        remaining <= remaining - COUNT_W'(1); offset <= offset + COUNT_W'(1);
                    end
                end
                if (eligible) begin
                    out_valid <= 1'b1;
                    upper_out <= head_upper.data; lower_out <= result_lower.data;
                    upper_payload_out <= head_upper.payload; lower_payload_out <= result_lower.payload;
                    context_out <= head_upper.owner; generation_out <= head_upper.generation;
                end
            end
        end
    end

    // synthesis translate_off
    initial begin
        if (DEPTH < 1 || (DEPTH & (DEPTH-1)) != 0 || FRAME_T < 2*DEPTH ||
            FRAME_T % (2*DEPTH) != 0 || DATA_W < 1 || PAYLOAD_W < 1 || GEN_W < 1 ||
            (CONTEXTS != 1 && CONTEXTS != 2)) $fatal(1, "COMM_PARAMETERS");
    end
    // synthesis translate_on
endmodule

module genefer_stream27_mdc_fifo_sync #(
    parameter int unsigned WORD_W = 53,
    parameter int unsigned DEPTH = 4
) (
    input logic clk, rst_n, advance,
    input logic [WORD_W-1:0] write_word,
    output logic [WORD_W-1:0] head
);
    generate if (DEPTH == 1) begin : register_cell
        logic occupied;
        logic [WORD_W-1:0] value;
        assign head = occupied ? value : '0;
        always_ff @(posedge clk or negedge rst_n) begin
            if (!rst_n) occupied <= 1'b0;
            else if (advance) occupied <= 1'b1;
        end
        always_ff @(posedge clk) if (advance) value <= write_word;
    end else begin : synchronous_ram
        localparam int unsigned PTR_W = $clog2(DEPTH);
        localparam int unsigned FILL_W = $clog2(DEPTH+1);
        logic [PTR_W-1:0] pointer, next_pointer;
        logic [FILL_W-1:0] filled;
        logic [WORD_W-1:0] memory [0:DEPTH-1];
        logic [WORD_W-1:0] prefetched;
        assign next_pointer = pointer + PTR_W'(1);
        assign head = (filled == FILL_W'(DEPTH)) ? prefetched : '0;
        // Distinct addresses for DEPTH>=2: old-data collision mode irrelevant.
        // No reset in this block: neither payload nor tag RAM is reset.
        always_ff @(posedge clk) begin
            if (advance) begin
                prefetched <= memory[next_pointer];
                memory[pointer] <= write_word;
            end
        end
        always_ff @(posedge clk or negedge rst_n) begin
            if (!rst_n) begin pointer <= '0; filled <= '0; end
            else if (advance) begin
                pointer <= next_pointer;
                if (filled != FILL_W'(DEPTH)) filled <= filled + FILL_W'(1);
            end
        end
    end endgenerate
endmodule

files.genefer_ntt_banked27_engine.sv:
// Experimental27-bit prime basis, Montgomery radix remains2^32.
// Full32-bit host words must be canonical residues<P. No rawdigit conversion.
// Simulation assertions enforce this precondition; production needs a validated producer.
// Wide routing candidate: supports up to 64 arithmetic and host lanes.
// Frozen 4/16-lane shared engine is unchanged; same modulus and schedule.
// Shared-multiplier candidate: pointwise work uses DIT(0,lhs,rhs), retaining y0.
// One Montgomery pipeline per lane; output-kind tags are six clocks deep.
// Both butterfly and pointwise RAM read-to-write distances are seven clocks.
// Control-predecode candidate: one explicit setup cycle per transform stage.
// Stage descriptors and root-counter increments are registered off the issue path.
// Vector/scalar/cache APIs and arithmetic pipelines match the frozen vector engine.
// Vector-host candidate. Scalar/root requests lose priority to any vector
// request; invalid vector requests do not fall back to scalar access.
// Vector lane h is bits [32*h+:32], logical address vector_addr+h.
// Power-of-two root-group comparison; frozen modulemem candidate unchanged.
// Root storage is twist D, combined forward/inverse 2H, post D per bank.
// Resource/timing benefit, if any, must be measured against inferred3D RAM.
// Bank-centric cached DIF/DIT prototype. Frozen parallel/cache engines unchanged.
// Each butterfly lane owns a physical bank pair chosen from KW wiring patterns.
// Root distribution uses structured XOR/rotation/broadcast networks, not one
// BANKS-input mux per arithmetic lane. Pointwise routing uses two bank halves.
module genefer_ntt_banked27_engine #(
    parameter int AW=16,
    parameter int LANES=4,
    parameter logic [31:0] P=32'd104857601,
    parameter logic [31:0] Q=32'd4190109697
) (
    input logic clk,rst_n,load_we,root_we,read_en,
    input logic [AW-1:0] host_addr,
    input logic [31:0] write_data,
    output logic read_valid,
    output logic [31:0] read_data,
    input logic vector_load_we,vector_read_en,
    input logic [AW-1:0] vector_addr,
    input logic [LANES-1:0] vector_lane_mask,
    input logic [LANES*32-1:0] vector_write_data,
    output logic vector_read_valid,host_error,
    output logic [LANES-1:0] vector_read_mask,
    output logic [LANES*32-1:0] vector_read_data,
    input logic start,inverse,dif,
    input logic [1:0] root_phase,op,
    input logic [4:0] size_log2,
    input logic [31:0] scale,
    output logic busy,done,error,
    output logic [63:0] cycles,butterflies,data_reads,data_writes,root_reads,wait_cycles
);
    localparam int LW=$clog2(LANES),KW=LW+1,BANKS=2*LANES;
    localparam int PW=KW>1 ? $clog2(KW) : 1;
    localparam int SIW=AW>1 ? $clog2(AW) : 1;
    localparam int RW=AW>KW ? AW-KW : 1;
    localparam int DEPTH=1 << (AW>KW ? AW-KW : 0);
    localparam int HALF_DEPTH=1 << (AW>KW+1 ? AW-KW-1 : 0);
    localparam int ROOT_DEPTH=2*DEPTH+2*HALF_DEPTH,RRW=$clog2(ROOT_DEPTH);
    localparam int MID_DEPTH=2*HALF_DEPTH,MRW=$clog2(MID_DEPTH);
    typedef enum logic [2:0] {IDLE,STAGE_SETUP,BF_READ,BF_DRAIN,MUL_READ,MUL_DRAIN} state_t;
    state_t state;
    logic [31:0] n,group_index,completed,base_addr,point_base,root_base;
    logic [4:0] lg,stage_bit,root_shift,stage_bit_d,setup_root_shift;
    logic [PW-1:0] pairing,rotation,pairing_d,rotation_d;
    logic [KW-1:0] base_bank,root_base_bank,root_mask,base_bank_d,root_base_bank_d;
    logic orientation,orientation_d,point_half,point_half_d,low_stage_d;
    logic [6:0] orientation_pipe,point_half_pipe;
    logic [1:0] active_op;
    logic active_inverse,active_dif;
    logic [31:0] active_scale,bf_lanes,mul_lanes,root_read_count;
    logic [31:0] stage_toggle_mask,stage_low_mask;
    logic [KW-1:0] stage_root_count;
    logic stage_low;
    logic [AW-1:0] fixed_mask;
    logic [SIW-1:0] fixed_source [0:AW-1];
    logic [AW-1:0] fixed_mask_options [0:AW-1];
    logic [SIW-1:0] fixed_source_options [0:AW-1][0:AW-1];
    logic [RRW-1:0] active_root_base,host_root_base;
    logic [KW-1:0] host_bank,host_bank_d;
    logic [RW-1:0] host_row;
    logic half_write_illegal;
    logic vector_request,vector_ok;
    logic [31:0] host_n;
    logic [LANES-1:0] effective_mask;
    logic [KW-1:0] vector_base_bank,vector_base_bank_d;
    logic [BANKS-1:0] data_re,data_we,root_re;
    logic [RW-1:0] data_ra [0:BANKS-1],data_wa [0:BANKS-1];
    logic [RRW-1:0] root_ra [0:BANKS-1];
    logic [31:0] data_w [0:BANKS-1],data_q [0:BANKS-1],root_q [0:BANKS-1];
    logic [RW-1:0] row_tag [0:6][0:BANKS-1];
    logic [LANES-1:0] bf_in_valid,mul_in_valid,bf_valid,mul_valid;
    logic [31:0] bf0 [0:LANES-1],bf1 [0:LANES-1],product [0:LANES-1];
    logic [31:0] root_rotate_option [0:BANKS-1][0:KW-1];
    logic [31:0] root_rotated [0:BANKS-1];
    logic [31:0] root_clip_option [0:BANKS-1][0:KW-1];
    logic [31:0] root_clip [0:BANKS-1];

    function automatic logic [KW-1:0] bank_of(input logic [AW-1:0] a);
        logic [KW-1:0] b;
        begin b=0;for(int j=0;j<AW;j=j+1) b[j%KW]=b[j%KW]^a[j];bank_of=b;end
    endfunction
    function automatic logic [KW-1:0] ror(input logic [KW-1:0] b,input logic [PW-1:0] r);
        ror=(b>>r)|(b<<(KW-int'(r)));
    endfunction
    function automatic int insert_zero(input int a,p);
        insert_zero=(a&((1<<p)-1))|((a>>p)<<(p+1));
    endfunction
    function automatic int remove_bit(input int a,p);
        remove_bit=(a&((1<<p)-1))|((a>>(p+1))<<p);
    endfunction
    function automatic logic [RRW-1:0] phase_base(input logic [1:0] phase_id);
        case(phase_id)
            0: phase_base=0;
