        logic [RW-1:0] post_read_addr,post_write_addr;
        assign read_twist=active_root_base==0;
        assign read_post=active_root_base==RRW'(DEPTH+2*HALF_DEPTH);
        assign read_middle=!read_twist && !read_post;
