files.genefer_stream27_mdc_commutator_slots_v2:
// Additive physical-slot successor. Compile with frozen commutator_sync.sv
// for genefer_stream27_mdc_fifo_sync; that helper and its RAM timing are unchanged.
// Every occupied output updates data/tags, including canceled generations.
// Finite tags MUST NOT be reused/re-enabled until old slots and commits drain.
module genefer_stream27_mdc_commutator_slots_v2 #(
    parameter int unsigned DATA_W = 27,
    parameter int unsigned PAYLOAD_W = 16,
    parameter int unsigned GEN_W = 8,
    parameter int unsigned DEPTH = 4,
    parameter int unsigned FRAME_T = 8,
    parameter int unsigned CONTEXTS = 1
) (
    input logic clk, rst_n,
    input logic in_slot_valid, frame_start,
    input logic [DATA_W-1:0] upper_in, lower_in,
    input logic [PAYLOAD_W-1:0] upper_payload, lower_payload,
    input logic context_in,
    input logic [GEN_W-1:0] generation_in,
    input logic [CONTEXTS-1:0] context_enabled,
    input logic [CONTEXTS*GEN_W-1:0] live_generations,
    // Registered OR of all stage errors freezes the chain after first fault.
    input logic quarantine,
    output logic out_slot_valid, out_frame_start, out_eligible, out_error,
    // Pre-edge fault authority for terminal commit; not a registered data port.
    output logic fault_pending,
    output logic [DATA_W-1:0] upper_out, lower_out,
    output logic [PAYLOAD_W-1:0] upper_payload_out, lower_payload_out,
    output logic context_out,
    output logic [GEN_W-1:0] generation_out
);
    localparam int unsigned COUNT_W = $clog2(FRAME_T+1);
    localparam int unsigned SHIFT = $clog2(DEPTH);
    typedef struct packed {
        logic valid;
        logic [DATA_W-1:0] data;
        logic [PAYLOAD_W-1:0] payload;
        logic owner;
        logic [GEN_W-1:0] generation;
    } word_t;
    localparam int unsigned WORD_W = $bits(word_t);
    logic [COUNT_W-1:0] remaining, offset, output_offset;
    logic frame_owner, output_owner;
    logic [GEN_W-1:0] frame_generation, output_generation;
    logic malformed, phase, advance, owner_bad, eligible;
    word_t x, y, head_upper, head_lower, write_upper, result_lower;
    logic [GEN_W-1:0] expected_generation;

    always_comb begin
        malformed = (frame_start && ((remaining != '0) || !in_slot_valid)) ||
                    (in_slot_valid && !frame_start && (remaining == '0)) ||
                    (!in_slot_valid && (remaining != '0)) ||
                    (in_slot_valid && (CONTEXTS == 1) && context_in) ||
                    (in_slot_valid && !frame_start && (remaining != '0) &&
                     ((context_in != frame_owner) || (generation_in != frame_generation)));
        phase = in_slot_valid && !frame_start && offset[SHIFT];
        x = '0; y = '0;
        x.valid = in_slot_valid; x.data = upper_in; x.payload = upper_payload;
        x.owner = context_in; x.generation = generation_in;
        y.valid = in_slot_valid; y.data = lower_in; y.payload = lower_payload;
        y.owner = context_in; y.generation = generation_in;
        write_upper = phase ? head_lower : x;
        result_lower = phase ? x : head_lower;
        owner_bad = (head_upper.valid != result_lower.valid) ||
                    (head_upper.valid && ((head_upper.owner != result_lower.owner) ||
                     (head_upper.generation != result_lower.generation))) ||
                    (head_upper.valid && (output_offset != '0) &&
                     ((head_upper.owner != output_owner) ||
                      (head_upper.generation != output_generation)));
        expected_generation = live_generations[GEN_W-1:0];
        if (CONTEXTS == 2)
            expected_generation = head_upper.owner ?
                GEN_W'(live_generations >> GEN_W) : live_generations[GEN_W-1:0];
        eligible = head_upper.valid && !owner_bad &&
                   (head_upper.generation == expected_generation) &&
                   (head_upper.owner ? ((CONTEXTS == 2) && context_enabled[CONTEXTS-1]) : context_enabled[0]);
        fault_pending = out_error || (!quarantine && (malformed || owner_bad));
        advance = rst_n && !quarantine && !fault_pending;
    end

    genefer_stream27_mdc_fifo_sync #(.WORD_W(WORD_W), .DEPTH(DEPTH)) upper_fifo (
        .clk(clk), .rst_n(rst_n), .advance(advance), .write_word(write_upper), .head(head_upper));
    genefer_stream27_mdc_fifo_sync #(.WORD_W(WORD_W), .DEPTH(DEPTH)) lower_fifo (
        .clk(clk), .rst_n(rst_n), .advance(advance), .write_word(y), .head(head_lower));

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_slot_valid <= 1'b0; out_frame_start <= 1'b0;
            out_eligible <= 1'b0; out_error <= 1'b0;
            remaining <= '0; offset <= '0; output_offset <= '0;
        end else begin
            out_slot_valid <= 1'b0; out_frame_start <= 1'b0; out_eligible <= 1'b0;
            if (!quarantine && (malformed || owner_bad)) out_error <= 1'b1;
            if (advance) begin
                if (in_slot_valid) begin
                    if (frame_start) begin
                        remaining <= COUNT_W'(FRAME_T-1); offset <= COUNT_W'(1);
                        frame_owner <= context_in; frame_generation <= generation_in;
                    end else begin
                        remaining <= remaining - COUNT_W'(1); offset <= offset + COUNT_W'(1);
                    end
                end
                if (head_upper.valid) begin
                    out_slot_valid <= 1'b1;
                    out_frame_start <= (output_offset == '0);
                    out_eligible <= eligible;
                    output_offset <= (output_offset == COUNT_W'(FRAME_T-1)) ? '0 : output_offset + COUNT_W'(1);
                    if (output_offset == '0) begin
                        output_owner <= head_upper.owner; output_generation <= head_upper.generation;
                    end
                    upper_out <= head_upper.data; lower_out <= result_lower.data;
                    upper_payload_out <= head_upper.payload; lower_payload_out <= result_lower.payload;
                    context_out <= head_upper.owner; generation_out <= head_upper.generation;
                end
            end
        end
    end

    // synthesis translate_off
    initial begin
        if (DEPTH < 1 || (DEPTH & (DEPTH-1)) != 0 || FRAME_T < 2*DEPTH ||
            FRAME_T % (2*DEPTH) != 0 || DATA_W < 1 || PAYLOAD_W < 1 || GEN_W < 1 ||
            (CONTEXTS != 1 && CONTEXTS != 2)) $fatal(1, "SLOTS_PARAMETERS");
    end
    // synthesis translate_on
endmodule

files.genefer_stream27_root_rom_prefetch.sv:
// Source-only S3 row-root wrapper. One synchronous read/edge, no async ROM
// access, no extra butterfly edge. Incoming physical row0 uses FIRST_ROOT;
// accepting row r prefetches root r+1 for the following physical row.
// FIRST_ROOT makes immediate post-reset row0 independent of retained ROM q.
// Initialize ROM from the exact compiler-produced R-form roots. A missing
// HEX_FILE is a preparation failure, not permission to fit unknown constants.
module genefer_stream27_root_rom_prefetch #(
    parameter int unsigned PERIOD = 4,
    parameter logic [26:0] FIRST_ROOT = 27'd0,
    parameter string HEX_FILE = ""
) (
    input logic clk, rst_n, in_slot_valid, frame_start,
    output logic [26:0] root
);
    generate if (PERIOD == 1) begin : constant_root
        assign root = FIRST_ROOT;
    end else begin : synchronous_root
        localparam int unsigned ADDR_W = $clog2(PERIOD);
        (* ramstyle = "M20K" *) logic [26:0] roots [0:PERIOD-1];
        logic [ADDR_W-1:0] current_row, following_row;
        logic [26:0] prefetched;
        assign following_row = frame_start ? ADDR_W'(1) : current_row + ADDR_W'(1);
        assign root = frame_start ? FIRST_ROOT : prefetched;
        initial $readmemh(HEX_FILE, roots);
        // No reset on ROM payload/read register; first-row constant bypass is
        // the eligibility-safe initialization mechanism.
        always_ff @(posedge clk)
            if (rst_n && in_slot_valid) prefetched <= roots[following_row];
        always_ff @(posedge clk or negedge rst_n) begin
            if (!rst_n) current_row <= '0;
            else if (in_slot_valid) current_row <= following_row;
        end
    end endgenerate
    // synthesis translate_off
    initial begin
        if (PERIOD < 1 || (PERIOD & (PERIOD-1)) != 0)
            $fatal(1, "FIELD_ROOT_PERIOD");
        if (PERIOD > 1 && HEX_FILE == "") $fatal(1, "FIELD_ROOT_ROM_MISSING");
    end
    // synthesis translate_on
endmodule

files.genefer_digit_reduce27_pipe.sv:
// Four register stages, II=1: accepted edge t responds at edge t+3.
// Ordinary inputs0..999999999 or signed32 -1 (FFFFFFFF) only.
// Invalid full-word inputs produce out_error, never a truncated residue.
module genefer_digit_reduce27_pipe #(
    parameter logic [31:0] P=32'd104857601,
    parameter int PAYLOAD_W=1
) (
    input logic clk,rst_n,in_valid,
    input logic [31:0] digit,
    input logic [PAYLOAD_W-1:0] payload_in,
    output logic out_valid,out_error,
    output logic [31:0] residue,
    output logic [PAYLOAD_W-1:0] payload_out
);
    localparam bit PARAM_OK=P<32'd134217728 && (64'(P)<<4)>64'd999999999;
    localparam logic [31:0] P8=P<<3;
    localparam logic [29:0] P4=30'(P)<<2;
    localparam logic [28:0] P2=29'(P)<<1;
    logic [2:0] good,bad;
    logic [29:0] s1;
    logic [28:0] s2;
    logic [27:0] s3;
    logic [PAYLOAD_W-1:0] tag1,tag2,tag3;
    logic legal;
    logic [31:0] normalized,first_difference;
    assign legal=PARAM_OK && (digit<=32'd999999999 || digit==32'hffffffff);
    assign normalized=digit==32'hffffffff ? P-32'd1 : digit;
    assign first_difference=normalized>=P8 ? normalized-P8 : normalized;

    // Data stages are valid-gated and intentionally not reset. No invalid
    // input reaches a narrowed arithmetic register.
    always_ff @(posedge clk)begin
        if(rst_n && in_valid && legal)s1<=first_difference[29:0];
        if(rst_n && good[0])s2<=29'(s1>=P4 ? s1-P4 : s1);
        if(rst_n && good[1])s3<=28'(s2>=P2 ? s2-P2 : s2);
        if(rst_n && in_valid)tag1<=payload_in;
        if(rst_n && (good[0] || bad[0]))tag2<=tag1;
        if(rst_n && (good[1] || bad[1]))tag3<=tag2;
    end
    always_ff @(posedge clk or negedge rst_n)begin
        if(!rst_n)begin
            good<='0;bad<='0;out_valid<=0;out_error<=0;residue<=0;payload_out<='0;
        end else begin
            good<={good[1:0],in_valid && legal};bad<={bad[1:0],in_valid && !legal};
            out_valid<=good[2];out_error<=bad[2];
            if(good[2])residue<={5'b0,27'(s3>=28'(P) ? s3-28'(P) : s3)};
            if(good[2] || bad[2])payload_out<=tag3;
        end
    end
    // synthesis translate_off
    initial begin
        if(!PARAM_OK)$fatal(1,"unsupported digit reducer modulus range");
        if(PAYLOAD_W<1)$fatal(1,"invalid digit reducer payload width");
    end
    always @(posedge clk)if(rst_n)begin
        if(good[0] && 32'(s1)>=P8)$fatal(1,"digit stage1 range");
        if(good[1] && s2>=29'(P4))$fatal(1,"digit stage2 range");
        if(good[2] && s3>=28'(P2))$fatal(1,"digit stage3 range");
        if(out_valid && (out_error || residue>=P))$fatal(1,"digit reducer output range");
    end
    // synthesis translate_on
endmodule

files.genefer_stream27_signed_boundary_reduce2:
// SOURCE-ONLY S3 candidate: accepted edge k responds at k+4, II=1.
// A frozen four-stage magnitude path (D3) plus one sign-output register.
// Full signed32 c0/c1 words are checked before magnitude narrowing; data are
// ordinary residues. Controller owns base/generation coherence and quarantine.
module genefer_stream27_signed_boundary_reduce27_pipe #(
    parameter logic [31:0] P=32'd104857601,
    parameter int AW=16,
    parameter int BLOCKS=8,
    parameter int PAYLOAD_W=1
) (
    input logic clk,rst_n,in_valid,boundary_high,
    input logic signed [31:0] correction,
    input logic [31:0] base,
    input logic [PAYLOAD_W-1:0] payload_in,
    output logic out_valid,out_error,
    output logic [31:0] residue,
    output logic [PAYLOAD_W-1:0] payload_out
);
    localparam logic [63:0] N=64'd1<<AW;
    localparam logic [63:0] K=64'd2*N+64'd24*64'(BLOCKS);
    localparam logic [63:0] BASE_MIN_A=64'd2*N+64'd5;
    localparam logic [63:0] BASE_MIN_B=(64'd2*K+64'd2)/64'd3+64'd1;
    localparam logic [63:0] BASE_MIN=BASE_MIN_A>BASE_MIN_B ? BASE_MIN_A : BASE_MIN_B;
    localparam bit GEOMETRY_OK=AW>=5 && AW<=16 && BLOCKS>=1 &&
        (BLOCKS & (BLOCKS-1))==0 && 64'(BLOCKS)<=N/64'd2;
    localparam bit FIELD_OK=P==32'd104857601 || P==32'd69206017 || P==32'd67239937;

    wire signed [32:0] wide_correction={correction[31],correction};
    wire [32:0] magnitude=correction[31] ? 33'(-wide_correction) : 33'(wide_correction);
    wire [32:0] admitted_limit=boundary_high ? 33'(K) : {1'b0,base}-33'd1;
    wire legal=GEOMETRY_OK && FIELD_OK && base>=32'(BASE_MIN) &&
        base<=32'd1000000000 && magnitude<=admitted_limit;
    // 0x80000000 is never legal in the frozen magnitude reducer. Passing a
    // rejected token as that poison preserves the child's exact D3 error/tag
    // path; 0xffffffff must NOT be used because it means legal signed -1 there.
    wire [31:0] magnitude_digit=legal ? magnitude[31:0] : 32'h80000000;
    logic magnitude_valid,magnitude_error;
    logic [31:0] magnitude_residue;
    logic [PAYLOAD_W:0] magnitude_payload;
    genefer_digit_reduce27_pipe #(.P(P),.PAYLOAD_W(PAYLOAD_W+1)) magnitude_path (
        .clk,.rst_n,.in_valid,.digit(magnitude_digit),
        .payload_in({correction[31],payload_in}),
        .out_valid(magnitude_valid),.out_error(magnitude_error),
        .residue(magnitude_residue),.payload_out(magnitude_payload)
    );
    always_ff @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            out_valid<=0;out_error<=0;residue<=0;payload_out<='0;
        end else begin
            out_valid<=magnitude_valid;
            out_error<=magnitude_error;
            if(magnitude_valid) begin
                // A negative multiple of P has residue0, not the noncanonical P.
                residue<=magnitude_payload[PAYLOAD_W] && magnitude_residue!=0 ?
                    P-magnitude_residue : magnitude_residue;
            end
            if(magnitude_valid || magnitude_error)payload_out<=magnitude_payload[PAYLOAD_W-1:0];
        end
    end
    // synthesis translate_off
    initial begin
        if(!GEOMETRY_OK)$fatal(1,"stream27 boundary reducer geometry");
        if(!FIELD_OK)$fatal(1,"stream27 boundary reducer field");
        if(PAYLOAD_W<1)$fatal(1,"stream27 boundary reducer payload width");
    end
    always @(posedge clk)if(rst_n)begin
        if(in_valid && legal && (magnitude>33'd999999999 || magnitude[32]))
            $fatal(1,"stream27 boundary reducer admitted magnitude");
        if(magnitude_valid && (magnitude_error || magnitude_residue>=P))
            $fatal(1,"stream27 boundary reducer magnitude output");
        if(out_valid && (out_error || residue>=P))
            $fatal(1,"stream27 boundary reducer signed output");
    end
    // synthesis translate_on
endmodule

files.genefer_stream27_epoch_protocol_v5.sv:
// Additive r17 registered-fault successor; frozen v4 remains unchanged.
// Additive repair of v3's process-level combinational cycle. Prospective
// descriptor lookup never reads fault/accept/quarantine signals; fault gating
// consumes lookup outputs, never supplies lookup inputs. No edge is added.
module genefer_stream27_epoch_protocol_v5 #(
    parameter int unsigned ROWS=8192,
    parameter int unsigned POINTWISE_FIRST=8308,
    parameter int unsigned SINK_FIRST=16618,
    parameter int unsigned EPOCH_W=16
) (
    input logic clk,rst_n,quarantine,external_fault_pending,
    input logic frame_begin,
    input logic [EPOCH_W-1:0] frame_epoch,
    input logic [7:0] frame_generation,
    input logic [31:0] frame_base,
    input logic correction_valid,
    input logic [EPOCH_W-1:0] correction_epoch,
    input logic [7:0] correction_generation,
    input logic cache_ready,
    input logic [EPOCH_W-1:0] cache_epoch,
    input logic [7:0] cache_generation,
    input logic pointwise_slot,pointwise_frame_start,
    input logic [7:0] pointwise_generation,
    input logic sink_slot,sink_frame_start,
    input logic [7:0] sink_generation,
    input logic context_enabled,
    input logic [7:0] live_generation,
    output logic frame_accept,correction_accept,
    output logic [31:0] correction_base,
    output logic pointwise_accept,commit_enable,
    output logic [EPOCH_W-1:0] pointwise_epoch,sink_epoch,
    output logic [$clog2(ROWS)-1:0] pointwise_row,sink_row,
    output logic [1:0] owner_count,
    output logic out_error,fault_pending
);
    localparam int ROW_W=$clog2(ROWS);
    logic [1:0] valid,received,ready;
    logic [EPOCH_W-1:0] epoch[0:1],next_epoch;
    logic [7:0] generation[0:1];
    logic [31:0] base[0:1],pw_first[0:1],sink_first[0:1];
    logic [31:0] cycle_count;
    logic sequence_initialized;
    logic bad,free_found,free_index,corr_found,corr_index,cache_found,cache_index;
    logic pw_found,pw_index,sink_found,sink_index,frame_owner_exists;
    logic [31:0] pw_age[0:1],sink_age[0:1];
    logic [1:0] corr_matches,cache_matches,pw_matches,sink_matches;
    wire stop=quarantine || out_error;
    assign owner_count={1'b0,valid[0]}+{1'b0,valid[1]};

    // Pure selection cone. In particular correction_base must remain stable
    // as external_fault_pending changes in response to validating this base.
    // A same-edge candidate is raw frame_begin, not a resulting acceptance.
    always_comb begin : lookup_values
        free_found=1'b0;free_index=1'b0;frame_owner_exists=1'b0;
