        pw_found=1'b0;pw_index=1'b0;sink_found=1'b0;sink_index=1'b0;
        corr_matches='0;cache_matches='0;pw_matches='0;sink_matches='0;
        correction_base='0;pointwise_epoch='0;sink_epoch='0;
        pointwise_row='0;sink_row='0;
