    // It cannot change which prospective descriptor/base was selected.
    always_comb begin : protocol_checks
        bad=1'b0;
        for(int i=0;i<2;i=i+1)begin
            if(valid[i])begin
                if(corr_matches[i] && received[i])bad=1'b1;
                if(cache_matches[i] && (!received[i] || ready[i]))bad=1'b1;
                if(pw_matches[i] && pointwise_slot && (!ready[i] ||
                   pointwise_generation!=generation[i] ||
                   pointwise_frame_start!=(pw_age[i]==0)))bad=1'b1;
                if(sink_matches[i] && sink_slot && (sink_generation!=generation[i] ||
                   sink_frame_start!=(sink_age[i]==0)))bad=1'b1;
                if(frame_begin && frame_epoch==epoch[i])bad=1'b1;
